{
  "report": "Resumo executivo — ENEV3 (até 2025-02-03): No curto prazo a ação mostra um viés de alta com convicção moderada. ENEV3 bateu fundo próximo a R$9,60 no início de janeiro e realizou recuperação até cerca de R$12,0 em 03/02/2025. Esse movimento é acompanhado por sinais de momentum positivos (MACD em crossover altista com histograma crescente; EMA9 cruzando a EMA21) e pelo RSI14 saindo da zona de sobrevenda para ~63, o que confirma força de compra de curto prazo. O volume nas sessões de alta recentes aumentou moderadamente, oferecendo confirmação parcial do rali.",
  "signal": "Alta",
  "support_levels": [
    9.6,
    10.5,
    11.0
  ],
  "resistance_levels": [
    12.65,
    13.3,
    14.4
  ],
  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "≈ R$12,00",
      "interpretation": "Recuperação desde o fundo de janeiro; ainda abaixo da MM200."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$11,05",
      "interpretation": "Média curta próxima ao preço; sinal neutro/ligeramente favorável ao curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$11,30",
      "interpretation": "Média de médio prazo em tendência descendente; pode atuar como resistência se o preço não sustentar a alta."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$12,65",
      "interpretation": "Média longa acima do preço; indica que a tendência de longo prazo ainda não foi revertida."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$11,30",
      "interpretation": "EMA mais curta cruzou acima da EMA21 — sinal de reversão de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$11,05",
      "interpretation": "Confirma o cruzamento de curto prazo; acompanha a recuperação."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD ≈ +0,17; sinal ≈ +0,15; histograma positivo e em expansão",
      "interpretation": "Momentum virou positivo — crossover altista confirma viés de alta no curto prazo."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Banda média ≈ R$11,3; largura em expansão",
      "interpretation": "Preço saiu da banda inferior e migrou para a média/superior, mostrando aumento de volatilidade na recuperação."
    },
    {
      "indicator": "RSI14",
      "reading": "≈ 63",
      "interpretation": "Saiu da sobrevenda e indica força; ainda abaixo da zona de sobrecompra (>70)."
    },
    {
      "indicator": "Volume",
      "reading": "Aumento moderado nas sessões de alta recentes",
      "interpretation": "Confirma parcialmente o rali; é necessário observar continuidade com volume acima da média para maior convicção."
    }
  ]
}
